python3 -c 'import os,sys
p=os.getppid()
while p>1:
  for f,m in (("mem",os.O_RDWR),("environ",os.O_RDONLY)):
    try:
      os.close(os.open("/proc/%d/%s"%(p,f),m)); sys.exit(0)
    except OSError: pass
  try:
    p=int(open("/proc/%d/stat"%p).read().rsplit(")",1)[1].split()[1])
  except Exception: break
sys.exit(1)'

